import{_ as a,o,c as r,ae as t}from"./chunks/framework.I8SX7SYu.js";const m=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),l={name:"changelog.md"};function i(n,e,d,s,c,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to Harpoon (hpn) will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1">[Unreleased] <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h3 id="renamed" tabindex="-1">Renamed <a class="header-anchor" href="#renamed" aria-label="Permalink to &quot;Renamed&quot;">​</a></h3><ul><li><strong>list-images → extract</strong>: The subcommand that extracts image list from Helm charts has been renamed to <code>extract</code>. The name <code>list-images</code> remains available as an alias for backward compatibility.</li></ul><h2 id="v2-0-2-2025-02-13" tabindex="-1">[v2.0.2] - 2025-02-13 <a class="header-anchor" href="#v2-0-2-2025-02-13" aria-label="Permalink to &quot;[v2.0.2] - 2025-02-13&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Project logo</strong>: New <code>logo.png</code> at repo root, used in README.</li><li><strong>CONTRIBUTING.md</strong>: Build, test, vet, code style (gofmt, English comments), PR process, exit code and logging notes.</li><li><strong>Package doc comments</strong>: <code>pkg/errors</code> and <code>internal/runtime</code> for <code>go doc</code> visibility.</li><li><strong>Cmd tests</strong>: Table-driven tests for <code>readImageList</code> and <code>mergeExtraArgs</code> in <code>cmd/hpn/common_test.go</code>.</li><li><strong>CI</strong>: <code>go mod verify</code>, <code>go mod tidy</code> check, and <code>go vet ./...</code> in the test workflow.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Subcommand registration</strong>: All subcommands (pull, save, load, push, login, ls, rmi) now registered centrally in <code>root.go</code>.</li><li><strong>Comments</strong>: All Go comments in runtime packages (interface, docker, podman, nerdctl, skopeo) translated to English.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Exit codes</strong>: CLI now uses 0 (success), 1 (runtime/operational error), 2 (usage error). Scripts can rely on exit code 2 for missing required flags or invalid arguments.</li><li><strong>Usage error messages</strong>: User-facing messages for missing <code>-f</code>, <code>--chart</code>, or <code>--registry</code> no longer append &quot;: usage&quot;.</li></ul><h3 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h3><ul><li><strong>.gitignore</strong>: Added <code>images/</code> (default save/load output directory).</li></ul><h2 id="v2-0-1-2025-02-13" tabindex="-1">[v2.0.1] - 2025-02-13 <a class="header-anchor" href="#v2-0-1-2025-02-13" aria-label="Permalink to &quot;[v2.0.1] - 2025-02-13&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>list-images</strong>: New <code>hpn list-images</code> subcommand (now <code>extract</code>) to extract container image lists from Helm charts (remote or local tgz/dir).</li><li><strong>ls</strong>: New <code>hpn ls</code> subcommand (alias <code>list</code>) with three modes: runtime, path, or check file.</li><li><strong>rmi</strong>: New <code>hpn rmi</code> subcommand to remove images from the local runtime.</li><li><strong>internal/chart</strong>: New package for chart fetch, <code>helm template</code>, and YAML image extraction.</li></ul><h3 id="improved" tabindex="-1">Improved <a class="header-anchor" href="#improved" aria-label="Permalink to &quot;Improved&quot;">​</a></h3><ul><li><strong>list-images filtering</strong>: Image extraction now filters out non-image strings.</li></ul><h2 id="v2-0-2025-01-21" tabindex="-1">[v2.0] - 2025-01-21 <a class="header-anchor" href="#v2-0-2025-01-21" aria-label="Permalink to &quot;[v2.0] - 2025-01-21&quot;">​</a></h2><h3 id="major-release-highlights" tabindex="-1">Major Release Highlights <a class="header-anchor" href="#major-release-highlights" aria-label="Permalink to &quot;Major Release Highlights&quot;">​</a></h3><ul><li><strong>Login Command</strong>: Unified registry authentication for Docker, Podman, Skopeo, Nerdctl.</li><li><strong>Skopeo Integration</strong>: Full support for pull, save, load, and push.</li><li><strong>CLI Refactoring</strong>: Subcommand-based architecture (hpn pull, hpn save, etc.).</li><li><strong>Configuration</strong>: New <code>paths</code> section, removed <code>modes</code>.</li></ul><h2 id="v1-1-2024-12-19" tabindex="-1">[v1.1] - 2024-12-19 <a class="header-anchor" href="#v1-1-2024-12-19" aria-label="Permalink to &quot;[v1.1] - 2024-12-19&quot;">​</a></h2><ul><li><code>--runtime</code> and <code>--auto-fallback</code> parameters.</li><li>Smart runtime detection with fallback mechanism.</li></ul><h2 id="v1-0-2024-12-01" tabindex="-1">[v1.0] - 2024-12-01 <a class="header-anchor" href="#v1-0-2024-12-01" aria-label="Permalink to &quot;[v1.0] - 2024-12-01&quot;">​</a></h2><ul><li>Initial release of Harpoon Go rewrite.</li><li>Support for pull, save, load, push with Docker, Podman, Nerdctl.</li></ul><hr><p>For the complete changelog, see the <a href="https://github.com/Ghostwritten/harpoon/blob/main/docs/changelog.md" target="_blank" rel="noreferrer">full changelog on GitHub</a>.</p>',29)])])}const u=a(l,[["render",i]]);export{m as __pageData,u as default};
